n="Toxin Study", fn="原位替换急救包，继承增益；里面备有治疗药水和抗毒药。", sk=140, tx="放置一个毒素研究，内含治疗药水和抗毒药剂，并提供急救包的所有增益。", zh="毒素研究"}, {en="Plague Doctor's Laboratory", fn="原位替换急救包，继承增益；里面备有治疗药水和药膏。", sk=300, tx="放置一个瘟疫医生实验室，内含治疗药水和药膏，并提供急救包的所有增益。", zh="瘟疫医生实验室"}}, fishing={{en="Fish Bowl", fn="全属性百分比增益，法系物理都吃。", sk=20, tx="放置一个小的鱼缸，使你和附近坐下的其他人所有属性提高8%，与王者祝福不叠加。", zh="鱼缸"}, {en="Fishing Rack", fn="原位替换鱼缸，继承增益；一段时间内能钓上优秀品质的鱼，并提供钓鱼技能鱼饵。", sk=140, tx="放置一个钓鱼架，使你能够钓到优秀的鱼，持续1 小时，提供钓鱼技能鱼饵，并提供鱼缸的所有增益。", zh="钓鱼架"}, {en="Fishing Hut", fn="原位替换鱼缸/钓鱼架，继承增益；一段时间内能钓上稀有品质的鱼，并提供钓鱼技能鱼饵。", sk=300, tx="放置一个钓鱼小屋，使你能够钓到稀有的鱼，持续1 小时，提供钓鱼技能鱼饵，并提供鱼缸的所有增益。", zh="钓鱼小屋"}}, herbalism={{en="Incense Candle", fn="", sk=20, tx="点燃一根熏香蜡烛，使你和附近坐下的其他人智力提高25点，与奥术智慧不叠加。", zh="熏香蜡烛"}, {en="Greenhouse", fn="原位替换蜡烛，继承增益；播下的种子会随时间长成草药，全队都能采。", sk=140, tx="放置一个温室，随着时间的推移，播种的种子会生长成草药，并提供熏香蜡烛的所有增益。", zh="温室"}, {en="Seed Hybridizer", fn="原位替换蜡烛/温室，继承增益；可把种子增殖或杂交成更稀有的种子。", sk=300, tx="放置一个种子杂交器，允许将种子繁殖或组合成更稀有的级别，并提供熏香蜡烛的所有增益。", zh="种子杂交器"}}, leatherworking={{en="Camp Tent", fn="野外便携旅店：帐篷旁就座即把休息经验补到满一级的 5%（已经超过则无效）。不占任何团队增益位。", sk=20, tx="搭建一座帐篷，使你和附近坐下的其他人获得充分休息经验值，最多可累积至当前等级所需经验值的5%。若已有的充分休息经验超过该数值，则不生效。", zh="营地帐篷"}, {en="Tanning Rack", fn="原位替换帐篷，继承帐篷全部效果；并可在野外制作特定制皮材料。", sk=140, tx="放置一个制革架，允许制造特定材料，并提供营地帐篷的所有增益。", zh="制革架"}, {en="Sewing Machine", fn="原位替换帐篷/制革架，继承全部效果；并充当野外缝纫机环境（高阶配方要用）。", sk=300, tx="放置一台缝纫机，可用于需要它的配方，并提供营地帐篷的所有增益。", zh="缝纫机"}}, mining={{en="Lodestone", fn="", sk=20, tx="竖起一块磁石，使你和附近坐下的其他人近战攻击强度提高90，与力量祝福互斥。", zh="磁石"}, {en="Rock Garden", fn="原位替换磁石，继承增益；并随时间就地长出普通矿点，全队都能采。", sk=140, tx="放置一个岩石园，随着时间的推移会生成普通的采矿点，并提供磁石的所有增益。", zh="岩石园"}, {en="Molten Foundry", fn="原位替换磁石/岩石园，继承增益；并放下熔火铸造厂（野外高阶熔炼）。", sk=300, tx="放置一个熔火铸造厂，可用于需要它的配方，并提供磁石的所有增益。", zh="熔火铸造厂"}}, skinning={{en="Camp Chair", fn="爆击对物理和法术同时生效。", sk=20, tx="组装一把营地椅子，使你和附近坐下的其他人所有法术和攻击的爆击几率提高2%，与枭兽光环不叠加。", zh="营地椅子"}, {en="Field Guide", fn="原位替换椅子，继承增益；任何人读一下就能获得【追踪野兽】。", sk=140, tx="放置一本野外指南，允许玩家阅读并获得追踪野兽技能，并提供营地椅子的所有增益。", zh="野外指南"}, {en="Trapper's Workbench", fn="原位替换椅子/野外指南，继承增益；台子上带 1 个陷阱给团队用。", sk=300, tx="放置一个捕兽者工作台，内含1个陷阱，并提供营地椅子的所有增益。", zh="捕兽者工作台"}}, tailoring={{en="Faction Banner", fn="部落/联盟各一款，只对本阵营就座的人生效。", sk=20, tx="展开一面旗帜，使你和附近坐着的本阵营的其他成员的精神提高32。与神圣之灵互斥。", zh="阵营旗帜"}, {en="Spinning Wheel", fn="原位替换旗帜，继承增益；并可在野外制作特定裁缝材料。", sk=140, tx="放置一个纺车，允许制造特定材料，并提供阵营旗帜的所有增益。", zh="纺车"}, {en="Loom", fn="原位替换旗帜/纺车，继承增益；并放下高阶织布机（顶级配方要用）。", sk=300, tx="放置一台织布机，可用于需要它的配方，并提供阵营旗帜的所有增益。", zh="织布机"}}}, sit=60},
